css:
.tpl-floral *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.tpl-floral,.tpl-floral{width:210mm;height:297mm}
.tpl-floral{font-family:Poppins,sans-serif;color:#3B2278}
.tpl-floral .page{position:relative;width:210mm;height:297mm;overflow:hidden;background:#FCF8EF}
.tpl-floral .strip{position:absolute;left:0;right:0;top:0;height:2.4mm;background:linear-gradient(90deg,#7A4FD1 0 16%,#2A6FD6 16% 32%,#14A39A 32% 48%,#3DB56B 48% 62%,#F2B71B 62% 76%,#F28A1B 76% 88%,#D3217B 88%)}
.tpl-floral .conf{position:absolute;left:0;top:0;width:210mm;height:297mm}
.tpl-floral .col{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center}
.tpl-floral .url{margin-top:5.2mm;font:700 7pt Poppins;letter-spacing:.2em;color:#4B2397}
.tpl-floral .pill{margin-top:2mm;padding:2.2mm 12mm;border-radius:6mm;color:#fff;font:700 9.4pt Poppins;letter-spacing:.07em;background:linear-gradient(90deg,#D3217B,#F28A1B 55%,#3DB56B);box-shadow:0 1mm 2.4mm rgba(211,33,123,.3),inset 0 0 0 .5mm rgba(255,255,255,.6)}
.tpl-floral .sc{position:relative;margin-top:3.2mm;width:128mm;height:30mm;display:flex;flex-direction:column;align-items:center;justify-content:center}
.tpl-floral .sc svg.scroll{position:absolute;inset:0;width:100%;height:100%}
.tpl-floral .sc .a{position:relative;font:700 15pt Lora,serif;letter-spacing:.07em;color:#3B2278;margin-top:-1mm}
.tpl-floral .sc .t{position:relative;font:italic 700 34pt/1.15 Lora,serif;margin-top:.2mm}.tpl-floral .sc .t span{background:linear-gradient(90deg,#4B2397,#D3217B);-webkit-background-clip:text;background-clip:text;color:transparent}
.tpl-floral .ded{margin-top:3.4mm;width:128mm;text-align:center;padding:2.4mm 0;border-radius:6mm;color:#fff;font:700 10pt Poppins;letter-spacing:.12em;background:linear-gradient(90deg,#0E9AA0,#35A653);box-shadow:0 1mm 2.4mm rgba(14,154,160,.3),inset 0 0 0 .55mm #fff,inset 0 0 0 .9mm #0E9AA0}
.tpl-floral .wr{margin-top:.5mm;width:93mm;height:93mm} .tpl-floral .wr svg{width:100%;height:100%}
.tpl-floral .nw{position:relative;margin-top:.5mm;width:168mm}
.tpl-floral .nw .tl,.tpl-floral .nw .tr{position:absolute;top:3.6mm;width:13mm;height:100%;background:linear-gradient(90deg,#3E1D78,#6A35B5)}
.tpl-floral .nw .tl{right:calc(100% - 5mm);clip-path:polygon(0 0,100% 0,100% 100%,0 100%,28% 50%)}
.tpl-floral .nw .tr{left:calc(100% - 5mm);clip-path:polygon(0 0,100% 0,72% 50%,100% 100%,0 100%)}
.tpl-floral .name{position:relative;z-index:2;text-align:center;padding:2.6mm 0;color:#fff;font:700 22pt Lora,serif;letter-spacing:.07em;
 background:linear-gradient(90deg,#D3217B,#F0508F 28%,#F28A1B 75%,#E5A91A);box-shadow:0 1.2mm 3mm rgba(211,33,123,.38),inset 0 0 0 .5mm #FFE29A,inset 0 0 0 1mm #D3217B,inset 0 0 0 1.35mm rgba(255,255,255,.75)}
.tpl-floral .name i{position:absolute;top:50%;width:2.6mm;height:2.6mm;background:#fff;transform:translateY(-50%) rotate(45deg)}
.tpl-floral .tag{margin-top:3.2mm;font:700 9pt Poppins;letter-spacing:.2em;color:#D9930B;display:flex;gap:3mm;align-items:center}
.tpl-floral .tag b{color:#5A2A9B;font-size:8pt}
.tpl-floral .hh{margin-top:2.4mm;font:700 16pt Lora,serif;color:#C77712;letter-spacing:.02em}
.tpl-floral .msg{margin-top:1.6mm;width:178mm;text-align:center;font:400 8pt/1.44 Lora,serif;color:#3B2278}
.tpl-floral .sub{margin-top:2.4mm;font:700 8.4pt Poppins;letter-spacing:.06em;color:#4B2397}
.tpl-floral .tok{margin-top:1.6mm;font:700 11pt Lora,serif;letter-spacing:.12em;color:#3B2278}
.tpl-floral .cv{margin-top:.8mm;display:flex;align-items:center;gap:4mm;font:700 25pt/1.1 Lora,serif;letter-spacing:.08em}.tpl-floral .cv span{background:linear-gradient(90deg,#4B2397,#D3217B);-webkit-background-clip:text;background-clip:text;color:transparent}
.tpl-floral .cv svg{width:4.6mm;height:4.6mm}
.tpl-floral .cy{margin-top:.6mm;font:700 12pt Lora,serif;letter-spacing:.1em;color:#C77712;display:flex;gap:3mm;align-items:center}
.tpl-floral .cy svg{width:2.4mm;height:2.4mm}
.tpl-floral .by{margin-top:.8mm;font:700 7.4pt Poppins;letter-spacing:.14em;color:#4B2397}
.tpl-floral .og{margin-top:2mm;font:700 8pt Lora,serif;letter-spacing:.14em;color:#D3217B}
.tpl-floral .nr{margin-top:.9mm;display:flex;justify-content:center;align-items:center;gap:2.2mm;font:700 8.6pt Poppins}
.tpl-floral .nr em{width:1.6mm;height:1.6mm;background:#F2B71B;transform:rotate(45deg);display:block}
.tpl-floral .bar{position:absolute;left:0;right:0;bottom:0;height:7.6mm;background:linear-gradient(90deg,#4B2397,#5A2A9B 50%,#4B2397);display:flex;align-items:center;justify-content:center;color:#fff;font:700 7.8pt Poppins;letter-spacing:.2em}
.tpl-floral .bar:before{content:"";position:absolute;left:0;right:0;top:0;height:.9mm;background:linear-gradient(90deg,#D3217B,#F28A1B,#F2B71B,#3DB56B,#14A39A,#2A6FD6)}
.tpl-floral .slot{position:absolute;left:22.75%;top:22.75%;width:54.5%;height:54.5%;border-radius:50%;overflow:hidden}
.tpl-floral .slot img.pimg{width:100%;height:100%;object-fit:cover;display:block}
.tpl-floral .role{margin-top:2.4mm;padding:1mm 7mm;border-radius:4mm;color:#fff;font:700 9pt Poppins;letter-spacing:.12em;background:linear-gradient(90deg,#0E9AA0,#35A653);box-shadow:0 .8mm 2mm rgba(14,154,160,.35),inset 0 0 0 .4mm rgba(255,255,255,.7)}
